-- Import verified user-supplied archived forecasts plus official F1 session results.
-- Atomic one-time restore; exact predictions are preserved, no missing choices are invented.
LOCK TABLE public.stages,public.sessions,public.forecasts,public.qual_assignments,public.players IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.stages WHERE key IN ('australia','china','japan','miami','canada','monaco')) <> 6 THEN RAISE EXCEPTION 'Archive restore stopped: expected six existing stages.'; END IF;
 IF (SELECT count(*) FROM public.sessions s JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco')) <> 10 THEN RAISE EXCEPTION 'Archive restore stopped: target session inventory changed.'; END IF;
 IF EXISTS (SELECT 1 FROM public.sessions s JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco') AND s.committed IS TRUE) THEN RAISE EXCEPTION 'Archive restore stopped: target session already committed.'; END IF;
 IF EXISTS (SELECT 1 FROM public.forecasts f JOIN public.sessions s ON s.id=f.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco')) OR EXISTS (SELECT 1 FROM public.qual_assignments q JOIN public.sessions s ON s.id=q.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco')) THEN RAISE EXCEPTION 'Archive restore stopped: target already has prediction rows.'; END IF;
 IF (SELECT count(*) FROM public.players WHERE id IN ('cb3526c4-c6e9-4e4e-900b-de20ec65d8bd','78c5252c-b475-4454-85d6-cc4a829d4b85','4c6d68b8-04b0-4358-88a6-292d1c09937f','d3b88ca8-b8f6-4ae8-9144-153560301346','62852b1d-5713-4c3f-8ae5-1a20bf00cc68','738d157b-83b3-4803-84a6-59a473c38b89','d97ea322-7905-4af1-92ff-52f1f359ab7f','a77a5455-40a6-49e8-91ae-ee5c6c178da0','dd71ab04-7d84-4ae3-8e27-56930f0ee848','2a3e37b6-52b3-4563-a443-aa94d09fe408','dde5a28d-dc61-4b8c-97df-cea636fee33e','e1b5725f-45c9-4d40-b202-1807fc32b862','54e15e6a-f437-44a7-896b-be8171f1ed51','1ae2c6ba-bc35-4e79-818f-54e20f52c629','21f4f2f5-2c51-4f18-8e6e-ea44f3b747b5','ad6d39f6-2de5-4a32-a720-87d790910aa0','0a363da2-119b-4c0e-910e-0ccad6471f93','330ad2d7-e012-4de8-830a-41737c7778e6','5dfe5940-9a08-4c40-b4e8-170cf2e2f71d','7a1bec91-5181-4f69-82ca-7b4401f3c8d3')) <> 20 THEN RAISE EXCEPTION 'Archive restore stopped: mapped players differ.'; END IF;
 IF EXISTS (SELECT 1 FROM public.sessions old JOIN public.stages st ON st.id=old.stage_id JOIN jsonb_array_elements($sessions$[["fb9585c7-e000-4d8e-9828-c02035bd907f","115907e3-3a8d-4f38-bc09-9ed6dc861638","australia","qual",["Russell"],"","",null],["fc81dc36-2ff1-4297-b53c-dd6cf27cfccb","115907e3-3a8d-4f38-bc09-9ed6dc861638","australia","race",["Russell","Antonelli","Leclerc","Hamilton","Norris","Verstappen","Bearman","Lindblad","Bortoleto","Gasly"],"Verstappen","",null],["43a710fd-92a3-4e24-a83f-69002c2754d8","d614b629-6769-41d6-8430-31514050ac17","china","qual",["Antonelli"],"","",null],["34e2b71c-94c6-41c2-b6ad-b247e4e9224e","d614b629-6769-41d6-8430-31514050ac17","china","sprint",["Russell","Leclerc","Hamilton","Norris","Antonelli","Piastri","Lawson","Bearman","Verstappen","Ocon"],"","",null],["516816ab-3508-4aa9-8922-ba59fca3bdee","d614b629-6769-41d6-8430-31514050ac17","china","race",["Antonelli","Russell","Hamilton","Leclerc","Bearman","Gasly","Lawson","Hadjar","Sainz","Colapinto"],"Antonelli","",null],["db2233c6-9f5d-4105-8551-4909db17e800","b910e2b8-c288-4041-9fca-5e8272b06aa3","japan","qual",["Antonelli"],"","",null],["b61df29f-ae5b-4693-8007-425b06a2f55a","b910e2b8-c288-4041-9fca-5e8272b06aa3","japan","race",["Antonelli","Piastri","Leclerc","Russell","Norris","Hamilton","Gasly","Verstappen","Lawson","Ocon"],"Antonelli","",null],["d16f9e03-29e5-46c9-be2f-09cba873e199","0c76ad99-fdbc-4744-8b52-317b6992e3e6","miami","qual",["Antonelli"],"","",null],["22318f0c-0226-4ce7-b671-2a418cf71ff0","0c76ad99-fdbc-4744-8b52-317b6992e3e6","miami","sprint",["Norris","Piastri","Leclerc","Russell","Verstappen","Antonelli","Hamilton","Gasly","Hadjar","Colapinto"],"","",null],["496fc47f-fdb8-48fb-ab90-f865af2d5195","0c76ad99-fdbc-4744-8b52-317b6992e3e6","miami","race",["Antonelli","Norris","Piastri","Russell","Verstappen","Hamilton","Colapinto","Leclerc","Sainz","Albon"],"Norris","",null],["6531f4a9-9330-4e3d-9e1c-08e0fb5094a2","09123817-900b-4933-acb4-5fc654e1a783","canada","