END $$;

UPDATE public.stages st SET has_sprint=(x.row->>2)::boolean,is_locked=true
FROM jsonb_array_elements($stage_rows$[["australia","115907e3-3a8d-4f38-bc09-9ed6dc861638",false],["china","d614b629-6769-41d6-8430-31514050ac17",true],["japan","b910e2b8-c288-4041-9fca-5e8272b06aa3",false],["miami","0c76ad99-fdbc-4744-8b52-317b6992e3e6",true],["canada","09123817-900b-4933-acb4-5fc654e1a783",true],["monaco","9e876055-a0d2-4296-9d9f-e2959ea45ccb",false]]$stage_rows$::jsonb) x(row)
WHERE st.id=(x.row->>1)::uuid AND st.key=x.row->>0;

INSERT INTO public.sessions(id,stage_id,type,results,fl_pilot,ov_pilot,is_locked,committed,committed_at,deadline_utc)
SELECT (x.row->>0)::uuid,(x.row->>1)::uuid,x.row->>3,
