), raw AS (
 SELECT s.*,
  (SELECT COALESCE(jsonb_object_agg(pos::text,to_jsonb(pilot)),'{}'::jsonb) FROM jsonb_array_elements_text(s.pred_order) WITH ORDINALITY p(pilot,pos) WHERE pilot<>'') AS predictions,
  (SELECT COALESCE(jsonb_agg(jsonb_build_object('label',bd.value->>0,'pts',(bd.value->>1)::integer)),'[]'::jsonb) FROM jsonb_array_elements(s.raw_breakdown) bd(value)) AS breakdown
 FROM source s
)
INSERT INTO public.forecasts(session_id,player_id,predictions,fl_pick,ov_pick,score,score_breakdown,scored_input)
SELECT session_id,player_id,predictions,fl,ov,score,breakdown,jsonb_build_object('predictions',predictions,'fl_pick',fl,'ov_pick',ov) FROM raw;

