FROM jsonb_array_elements($bonuses$[["115907e3-3a8d-4f38-bc09-9ed6dc861638","1ae2c6ba-bc35-4e79-818f-54e20f52c629",18,18],["115907e3-3a8d-4f38-bc09-9ed6dc861638","ad6d39f6-2de5-4a32-a720-87d790910aa0",18,18],["d614b629-6769-41d6-8430-31514050ac17","1ae2c6ba-bc35-4e79-818f-54e20f52c629",2,2],["d614b629-6769-41d6-8430-31514050ac17","ad6d39f6-2de5-4a32-a720-87d790910aa0",2,2],["b910e2b8-c288-4041-9fca-5e8272b06aa3","1ae2c6ba-bc35-4e79-818f-54e20f52c629",11,11],["b910e2b8-c288-4041-9fca-5e8272b06aa3","ad6d39f6-2de5-4a32-a720-87d790910aa0",11,11],["0c76ad99-fdbc-4744-8b52-317b6992e3e6","1ae2c6ba-bc35-4e79-818f-54e20f52c629",2,2],["0c76ad99-fdbc-4744-8b52-317b6992e3e6","ad6d39f6-2de5-4a32-a720-87d790910aa0",2,2],["09123817-900b-4933-acb4-5fc654e1a783","1ae2c6ba-bc35-4e79-818f-54e20f52c629",1,1],["09123817-900b-4933-acb4-5fc654e1a783","ad6d39f6-2de5-4a32-a720-87d790910aa0",1,1],["9e876055-a0d2-4296-9d9f-e2959ea45ccb","1ae2c6ba-bc35-4e79-818f-54e20f52c629",1,1],["9e876055-a0d2-4296-9d9f-e2959ea45ccb","ad6d39f6-2de5-4a32-a720-87d790910aa0",1,1]]$bonuses$::jsonb) x(row);
UPDATE public.players p SET base_pts=COALESCE(p.base_pts,0)+(x.row->>1)::integer
FROM jsonb_array_elements($deltas$[["cb3526c4-c6e9-4e4e-900b-de20ec65d8bd",62],["78c5252c-b475-4454-85d6-cc4a829d4b85",56],["4c6d68b8-04b0-4358-88a6-292d1c09937f",49],["d3b88ca8-b8f6-4ae8-9144-153560301346",73],["62852b1d-5713-4c3f-8ae5-1a20bf00cc68",19],["738d157b-83b3-4803-84a6-59a473c38b89",124],["d97ea322-7905-4af1-92ff-52f1f359ab7f",182],["a77a5455-40a6-49e8-91ae-ee5c6c178da0",139],["dd71ab04-7d84-4ae3-8e27-56930f0ee848",183],["2a3e37b6-52b3-4563-a443-aa94d09fe408",12],["dde5a28d-dc61-4b8c-97df-cea636fee33e",147],["e1b5725f-45c9-4d40-b202-1807fc32b862",134],["54e15e6a-f437-44a7-896b-be8171f1ed51",141],["1ae2c6ba-bc35-4e79-818f-54e20f52c629",35],["21f4f2f5-2c51-4f18-8e6e-ea44f3b747b5",30],["ad6d39f6-2de5-4a32-a720-87d790910aa0",35],["0a363da2-119b-4c0e-910e-0ccad6471f93",159],["330ad2d7-e012-4de8-830a-41737c7778e6",107],["5dfe5940-9a08-4c40-b4e8-170cf2e2f71d",73],["7a1bec91-5181-4f69-82ca-7b4401f3c8d3",103]]$deltas$::jsonb) x(row) WHERE p.id=(x.row->>0)::uuid;

INSERT INTO public.score_recalculation_audit(stage_id,session_id,actor,status,details)
SELECT (x.row->>0)::uuid,NULL,NULL,'completed',jsonb_build_object('kind','verified_archive_restore','event_key',x.row->>1,'forecast_rows',(x.row->>2)::integer,'qual_rows',(x.row->>3)::integer,'newcomer_bonuses',(x.row->>4)::integer,'score_total',(x.row->>5)::integer,'source','verified archived forecasts and official F1 classifications')
FROM jsonb_array_elements($audit$[["115907e3-3a8d-4f38-bc09-9ed6dc861638","australia",10,10,2,275],["d614b629-6769-41d6-8430-31514050ac17","china",20,10,2,306],["b910e2b8-c288-4041-9fca-5e8272b06aa3","japan",12,11,2,335],["0c76ad99-fdbc-4744-8b52-317b6992e3e6","miami",28,0,2,302],["09123817-900b-4933-acb4-5fc654e1a783","canada",26,11,2,405],["9e876055-a0d2-4296-9d9f-e2959ea45ccb","monaco",18,0,2,240]]$audit$::jsonb) x(row);

DO $$ BEGIN
 IF (SELECT count(*) FROM public.sessions s JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco') AND s.committed IS TRUE)<>15 THEN RAISE EXCEPTION 'Archive restore verification failed: session count.'; END IF;
 IF (SELECT count(*) FROM public.forecasts f JOIN public.sessions s ON s.id=f.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))<>114 THEN RAISE EXCEPTION 'Archive restore verification failed: race/sprint forecast count.'; END IF;
 IF (SELECT count(*) FROM public.qual_assignments q JOIN public.sessions s ON s.id=q.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))<>42 THEN RAISE EXCEPTION 'Archive restore verification failed: qualifying count.'; END IF;
 IF (SELECT count(*) FROM public.stage_newcomer_bonuses b JOIN public.stages st ON st.id=b.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))<>12 THEN RAISE EXCEPTION 'Archive restore verification failed: newcomer bonus count.'; END IF;
 IF (SELECT COALESCE(sum(score),0) FROM public.forecasts f JOIN public.sessions s ON s.id=f.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))+(SELECT COALESCE(sum(score),0) FROM public.qual_assignments q JOIN public.sessions s ON s.id=q.session_id JOIN public.stages st ON st.id=s.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))+(SELECT COALESCE(sum(points),0) FROM public.stage_newcomer_bonuses b JOIN public.stages st ON st.id=b.stage_id WHERE st.key IN ('australia','china','japan','miami','canada','monaco'))<>1863 THEN RAISE EXCEPTION 'Archive restore verification failed: total is not 1863.'; END IF;
END $$;
